            category: prod.category,
            size: prod.size,
            color: prod.color,
            price: prod.price,
            cost: prod.cost,
            wholesalePrice: prod.wholesalePrice,
            wholesaleMinQuantity: prod.wholesaleMinQuantity,
            stock: prod.stock,
            minStock: prod.minStock,
            sku: prod.sku,
            description: prod.description || '',
            barcode: prod.barcode || '',
            imageUrls: prod.imageUrls || [],
